#mg-coco-refinado .buy{width:100%;display:flex;align-items:center;justify-content:center;gap:12px;border:0;border-radius:12px;background:#18a558;color:#fff;padding:18px 20px;font:700 16px Arial,sans-serif;cursor:pointer;transition:background .2s}

