#mg-almendras-refinado h2,#mg-almendras-refinado h3,#mg-almendras-refinado p{margin:0}

#mg-almendras-refinado .card p{margin-top:7px}

#mg-almendras-refinado .buy{width:100%;display:flex;align-items:center;justify-content:center;gap:12px;border:0;border-radius:12px;background:#18a558;color:#fff;padding:18px 20px;font:700 16px Arial,sans-serif;cursor:pointer;transition:background .2s}

#mg-almendras-refinado .arrow{margin-left:auto}

#mg-almendras-refinado .status{min-height:25px;text-align:center;font-size:14px;margin-top:8px}

#mg-almendras-refinado details{border-bottom:1px solid #dbece5;padding:18px 0}

#mg-almendras-refinado .mg-cart{position:fixed;inset:0 0 0 auto;width:min(440px,100%);height:100dvh;max-height:none;max-width:none;margin:0;border:0;padding:25px;background:#fff;color:#16362b;z-index:2147483647;overflow:auto;box-shadow:-12px 0 50px #0002}

