#mg-slipper-v2 {

}

#mg-slipper-v2 *,

#mg-slipper-v2 h2,

#mg-slipper-v2 h3,

#mg-slipper-v2 p,

#mg-slipper-v2 h2 span,

HERO

#mg-slipper-v2 .mgs2-hero .mgs2-lead { margin: 14px auto 0; color: var(--mg-text); font-size: 16px; font-weight: 750;

IMAGEN EXPLICATIVA

BENEFICIOS

#mg-slipper-v2 .mgs2-benefits h3 { margin-bottom: 20px; font-size: clamp(25px, 3.5vw, 34px);

#mg-slipper-v2 .mgs2-benefit-list { max-width: 680px; margin: 0 auto; display: flex; flex-direction: column; gap: 8px; text-align: left;

#mg-slipper-v2 .mgs2-benefit strong { color: var(--mg-text);

CIERRE

#mg-slipper-v2 .mgs2-closing h3 { max-width: 670px; margin: 0 auto 15px; font-size: clamp(24px, 3.4vw, 32px);

#mg-slipper-v2 .mgs2-closing p { max-width: 640px; margin: 0 auto 11px; color: var(--mg-muted); font-size: 15px;

#mg-slipper-v2 .mgs2-closing .mgs2-bold { margin-bottom: 0; color: var(--mg-text); font-weight: 750;

SELECTOR DE TALLES

#mg-slipper-v2 .mgs2-sizes h3 { margin-bottom: 9px; font-size: clamp(26px, 3.5vw, 34px);

#mg-slipper-v2 .mgs2-size-intro { margin-bottom: 20px; color: var(--mg-muted); font-size: 14px;

#mg-slipper-v2 .mgs2-size { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px; min-width: 0; min-height: 92px; padding: 12px 5px 9px; background: #fff; color: var(--mg-text); border: 1.5px solid var(--mg-border); border-radius: 11px; cursor: pointer; font-family: inherit; text-transform: none; letter-spacing: 0; transition border-color .2s, background .2s, transform .2s;

#mg-slipper-v2 .mgs2-size.is-selected { border: 2px solid var(--mg-green); background: #edf8f1;

#mg-slipper-v2 .mgs2-size.is-selected

ESTADO DE SELECCIÓN

#mg-slipper-v2 .mgs2-selected { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 13px 16px; margin-bottom: 13px; border-radius: 10px; background: var(--mg-soft); border: 1px solid var(--mg-border); text-align: left;

#mg-slipper-v2 .mgs2-selected > span { color: var(--mg-muted); font-size: 13px;

