} cta.dataset.initialized = "true";

/* MENSAJE AL USUARIO */ function showMessage(message) { if (feedback) { feedback.textContent = message;

/* BUSCAR FORMULARIO DEL PRODUCTO */ function findProductForm() { const forms = Array.from( document.querySelectorAll(

'form[action*="/cart/add"]'

)

).filter(function (form) { return !section.contains(form);

}); if (!forms.length) return null;

/* Priorizar formulario visible con variante */ const visibleForm = forms.find(function (form) { const visible = form.getClientRects().length > 0; const variantInput = form.querySelector(

'[name="id"]'

); return visible && variantInput;

}); return visibleForm || forms.find(function (form) { return form.querySelector('[name="id"]');

}) || forms[0];

/* MOSTRAR SELECTOR DEL TEMA */ function showProductOptions(form) { const target = form || document.querySelector(

'variant-selects, variant-radios, ' +

'[class*="variant-picker"], ' +

'[class*="product-form"]'

); if (target) { target.scrollIntoView({ behavior: "smooth", block: "center"

});

/* COMPROBAR VARIANTE SELECCIONADA */ function getSelectedVariant(form) { const variantInput = form.querySelector(

); if (!variantInput || !variantInput.value) { return null;

} const variantId = String(variantInput.value).trim(); if (!/^\d+$/.test(variantId)) { return null;

} return variantId;

/* BOTÓN NATIVO DEL TEMA */ function findNativeButton(form) { const buttons = Array.from( form.querySelectorAll(

'button[type="submit"], ' +

'input[type="submit"], ' +

'button[name="add"], ' +

'button[id*="ProductSubmitButton"]'

); return buttons.find(function (button) { return button.getClientRects().length > 0;

}) || buttons[0] || null;

/* CLICK PRINCIPAL */ cta.addEventListener("click", function () { const form = findProductForm(); if (!form) { showMessage(

"Seleccioná tu talle en las opciones del producto."

); showProductOptions(null); return;

/* Verificar que Shopify tenga un talle */ const variantId = getSelectedVariant(form); if (!variantId) { showMessage(

"Primero seleccioná el talle que querés."

); showProductOptions(form); return;

/* Delegar compra al botón real */ const nativeButton = findNativeButton(form); if (nativeButton) { if (nativeButton.disabled || nativeButton.getAttribute("aria-disabled") === "true") { showMessage(

"Revisá la disponibilidad del talle seleccionado."

} showMessage("Agregando al carrito...");

