} return false;

/* AGREGAR AL CARRITO */ button.addEventListener("click",async function(){ if(button.disabled)return; button.disabled=true; label.textContent="Agregando..."; setMessage("",false); try{ const variant=Number(getVariant()); if(!Number.isSafeInteger(variant)||variant s.id)

